    programmes = [
        ('school-sports-coaching','School Sports<br>& Coaching','Coaching, activities and team support for your school.','school','A school football team with their coaches','SCHOOLS & COLLEGES'),
        ('early-years-fundamentals','Early Years<br>& Fundamentals','Play-based movement and ball skills for preschools.','early-years','A young child kicking a football','PRESCHOOLS'),
        ('individual-performance-coaching','Individual &<br>Performance Coaching','Personal attention and purposeful practice for developing players.','individual-coaching','A Proteus coach working with one football player on passing skills','INDIVIDUAL + SMALL GROUP'),
        ('holiday-programmes','Holiday<br>Programmes','Sport, games and skill development over the school holidays.','holiday','Children and Proteus coaches together at a holiday programme','SCHOOL HOLIDAYS'),
        ('academy','Proteus<br>Academy','Football and basketball development alongside school and club sport.','academy-2027','Proteus Academy 2027 expressions of interest for football and basketball','2027 INTAKE'),
        ('coach-development','Coach<br>Development','Practical experience, workshops and support for developing coaches.','team','The Proteus coaching team','COACHES & ORGANISATIONS')
    ]
    rail = ''.join(f'''<article class="rail-card" data-slide><a href="/{slug}/"><div class="rail-image rail-image-{slug}">{photo(img,alt)}<span class="rail-card-index">0{i}</span><span class="rail-card-arrow" aria-hidden="true">↗</span></div><div class="rail-card-body"><p class="eyebrow">{label}</p><h3>{title}</h3><p>{desc}</p></div></a></article>''' for i,(slug,title,desc,img,alt,label) in enumerate(programmes,1))
