    instagram_icon = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="12" cy="12" r="4.2" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="17.5" cy="6.7" r="1.1" fill="currentColor"/></svg>'
    instagram_posts = [
        ('ig-hiring','DUR0wjViSjG','Coaching opportunities at Proteus Sports Group'),
        ('training','DPPnMvgk--7','Individual football training with Proteus'),
        ('ig-claudia-alex','DPkJmvYExJB','Meet Proteus coaches Claudia and Alex'),
        ('ig-team-day','DP2NqU4k4BK','The Proteus team connecting with future sports coaches'),
        ('ig-tom-caleb','DMeu8RvpWD_','Meet Proteus coaches Tom and Caleb'),
        ('coaches','DKtZIb4pvYF','Meet Proteus coach Ollie')
    ]
    instagram_tiles = ''.join(f'<a class="instagram-post" href="https://www.instagram.com/p/{post}/" target="_blank" rel="noopener noreferrer" aria-label="{escape(alt,quote=True)} — view on Instagram">{photo(img,alt)}<span class="instagram-post-icon">{instagram_icon}</span><span class="instagram-post-caption">View on Instagram ↗</span></a>' for img,post,alt in instagram_posts)
